/** Immutable public UI generated by an Agent; text remains the readable fallback. */
export interface InteractiveResponse {
  format: 'openui';
  catalog_version: 'nano-iui-1';
  source: string;
  source_mode?: 'patch';
  supersedes_message_id?: string;
}
export interface MessageInteractive extends InteractiveResponse {
  superseded_by?: string;
  read_only?: boolean;
}
export interface InteractionReplyInput {
  source_message_id: string;
  action_id?: string;
  event?: { type: 'continue_conversation'; message: string; context?: unknown; form_name?: string; label?: string };
  state: Record<string, unknown>;
}
export interface InteractionSnapshot extends Omit<InteractionReplyInput, 'source_message_id'> {
  source_message_id: string | null;
  source_summary: string;
  agent_id: string;
  action_label?: string;
  fields: { name: string; label: string; value: unknown; display_value?: string }[];
}
/** Private-chat context captured when sending text, never a public submission. */
export interface InteractionContextInput {
  source_message_id: string;
  state: Record<string, unknown>;
  interacted_at?: number;
}
export interface InteractionContext extends InteractionContextInput {
  source_summary: string;
  agent_id: string;
  fields: InteractionSnapshot['fields'];
}
/** Editable column shown while comparing this device's draft with another device's.
 *
 * Deliberately not `InteractionSnapshot['fields']`: that type also feeds
 * `InteractionContext.fields`, which is serialized verbatim into model input. Adding
 * `options` here must not change a single byte the model sees.
 */
export interface InteractionDraftField {
  name: string;
  label: string;
  value: unknown;
  /** Readable text for choice-like fields. */
  display_value?: string;
  /** Returned only here so a client can render its own local value with the same labels. */
  options?: { label: string; value: string }[];
}
export interface InteractionDraft {
  can_interact?: boolean;
  read_only?: boolean;
  superseded_by?: string | null;
  draft_revision: number;
  updated_at?: string | null;
  state: Record<string, unknown>;
  submission_message_id: string | null;
  /** Read-only labels for the 409 field comparison; never enters model input. */
  fields?: InteractionDraftField[];
}
